// Import pm_tasks via Supabase REST using the secret key (bypasses RLS).
//
// Usage (PowerShell):
//   $env:SUPABASE_SERVICE_ROLE_KEY="sb_secret_..."   # or legacy service_role JWT
//   node supabase/import_pm_tasks.mjs
//
// The key is read ONLY from the environment — never hard-code it here.
// Source rows: data/pm_tasks_import.json (generated by scripts/import-pm-tasks.py).
// Safe to re-run: deletes matching (equipment, name_en, task_no) keys first,
// then inserts. Never deletes other equipments' tasks.

import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const rows = JSON.parse(await readFile(path.join(ROOT, "data", "pm_tasks_import.json"), "utf-8"));

const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
if (!key) {
  console.error("Missing $env:SUPABASE_SERVICE_ROLE_KEY");
  process.exit(1);
}

// Project REST base (no /rest/v1 suffix); derive from the publishable config if needed.
const base = (process.env.SUPABASE_URL || "https://tdbuvnzwrakywtvnnewl.supabase.co/rest/v1").replace(/\/$/, "");
const headers = {
  apikey: key,
  Authorization: `Bearer ${key}`,
  "Content-Type": "application/json",
  Prefer: "return=minimal",
};

// Delete by key in batches to keep filters readable.
function eq(col, val) {
  return `${col}=eq.${encodeURIComponent(val)}`;
}
for (const r of rows) {
  // PostgREST AND of three eq filters.
  const url = `${base}/pm_tasks?${eq("equipment", r.equipment)}&${eq("name_en", r.name_en)}&${eq("task_no", r.task_no)}`;
  const res = await fetch(url, { method: "DELETE", headers });
  if (!res.ok) {
    console.error(`Delete failed for ${r.equipment}/${r.task_no}: ${res.status} ${await res.text()}`);
    process.exit(1);
  }
}

const res = await fetch(`${base}/pm_tasks`, {
  method: "POST",
  headers,
  body: JSON.stringify(rows),
});
if (!res.ok) {
  console.error(`Insert failed: ${res.status} ${await res.text()}`);
  process.exit(1);
}
console.log(`Imported ${rows.length} pm_tasks rows.`);
